        [Fact]
        public void ThermalResistivity_QuantityInfo_ReturnsQuantityInfoDescribingQuantity()
        {
            ThermalResistivityUnit[] unitsOrderedByName = EnumHelper.GetValues<ThermalResistivityUnit>().OrderBy(x => x.ToString(), StringComparer.OrdinalIgnoreCase).ToArray();
            var quantity = new ThermalResistivity(1, ThermalResistivityUnit.KelvinMeterPerWatt);

            QuantityInfo<ThermalResistivity, ThermalResistivityUnit> quantityInfo = quantity.QuantityInfo;

            Assert.Equal("ThermalResistivity", quantityInfo.Name);
            Assert.Equal(ThermalResistivity.Zero, quantityInfo.Zero);
            Assert.Equal(ThermalResistivity.BaseUnit, quantityInfo.BaseUnitInfo.Value);
            Assert.Equal(unitsOrderedByName, quantityInfo.Units);
            Assert.Equal(unitsOrderedByName, quantityInfo.UnitInfos.Select(x => x.Value));
            Assert.Equal(ThermalResistivity.Info, quantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity)quantity).QuantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity<ThermalResistivityUnit>)quantity).QuantityInfo);
        }

