        [Fact]
        public void ConversionRoundTrip()
        {
            ThermalResistivity kelvinmeterperwatt = ThermalResistivity.FromKelvinMetersPerWatt(3);
            Assert.Equal(3, ThermalResistivity.FromHourFeetFahrenheitPerBtu(kelvinmeterperwatt.HourFeetFahrenheitPerBtu).KelvinMetersPerWatt);
            Assert.Equal(3, ThermalResistivity.FromKelvinMetersPerWatt(kelvinmeterperwatt.KelvinMetersPerWatt).KelvinMetersPerWatt);
            Assert.Equal(3, ThermalResistivity.FromSecondInchesFahrenheitPerBtu(kelvinmeterperwatt.SecondInchesFahrenheitPerBtu).KelvinMetersPerWatt);
        }

        [Fact]
        public void ArithmeticOperators()
        {
            ThermalResistivity v = ThermalResistivity.FromKelvinMetersPerWatt(1);
            Assert.Equal(-1, -v.KelvinMetersPerWatt);
            Assert.Equal(2, (ThermalResistivity.FromKelvinMetersPerWatt(3) - v).KelvinMetersPerWatt);
            Assert.Equal(2, (v + v).KelvinMetersPerWatt);
            Assert.Equal(10, (v * 10).KelvinMetersPerWatt);
            Assert.Equal(10, (10 * v).KelvinMetersPerWatt);
            Assert.Equal(2, (ThermalResistivity.FromKelvinMetersPerWatt(10) / 5).KelvinMetersPerWatt);
            Assert.Equal(2, ThermalResistivity.FromKelvinMetersPerWatt(10) / ThermalResistivity.FromKelvinMetersPerWatt(5));
        }

        [Fact]
        public void ComparisonOperators()
        {
            ThermalResistivity oneKelvinMeterPerWatt = ThermalResistivity.FromKelvinMetersPerWatt(1);
            ThermalResistivity twoKelvinMetersPerWatt = ThermalResistivity.FromKelvinMetersPerWatt(2);

            Assert.True(oneKelvinMeterPerWatt < twoKelvinMetersPerWatt);
            Assert.True(oneKelvinMeterPerWatt <= twoKelvinMetersPerWatt);
            Assert.True(twoKelvinMetersPerWatt > oneKelvinMeterPerWatt);
            Assert.True(twoKelvinMetersPerWatt >= oneKelvinMeterPerWatt);

            Assert.False(oneKelvinMeterPerWatt > twoKelvinMetersPerWatt);
            Assert.False(oneKelvinMeterPerWatt >= twoKelvinMetersPerWatt);
            Assert.False(twoKelvinMetersPerWatt < oneKelvinMeterPerWatt);
            Assert.False(twoKelvinMetersPerWatt <= oneKelvinMeterPerWatt);
        }

