        [Fact]
        public void ToString_ReturnsValueAndUnitAbbreviationInCurrentCulture()
        {
            using var _ = new CultureScope("en-US");
            Assert.Equal("1 (h·ft·°F)/BTU", new ThermalResistivity(1, ThermalResistivityUnit.HourFootFahrenheitPerBtu).ToString());
            Assert.Equal("1 (m·K)/W", new ThermalResistivity(1, ThermalResistivityUnit.KelvinMeterPerWatt).ToString());
            Assert.Equal("1 (s·in·°F)/BTU", new ThermalResistivity(1, ThermalResistivityUnit.SecondInchFahrenheitPerBtu).ToString());
        }

        [Fact]
        public void ToString_WithSwedishCulture_ReturnsUnitAbbreviationForEnglishCultureSinceThereAreNoMappings()
        {
            // Chose this culture, because we don't currently have any abbreviations mapped for that culture and we expect the en-US to be used as fallback.
            var swedishCulture = CultureInfo.GetCultureInfo("sv-SE");

            Assert.Equal("1 (h·ft·°F)/BTU", new ThermalResistivity(1, ThermalResistivityUnit.HourFootFahrenheitPerBtu).ToString(swedishCulture));
            Assert.Equal("1 (m·K)/W", new ThermalResistivity(1, ThermalResistivityUnit.KelvinMeterPerWatt).ToString(swedishCulture));
            Assert.Equal("1 (s·in·°F)/BTU", new ThermalResistivity(1, ThermalResistivityUnit.SecondInchFahrenheitPerBtu).ToString(swedishCulture));
        }

